      { id: 3, question: 'What tool is commonly used for visual regression testing with Playwright?', options: ['Jasmine', 'Playwright with built-in screenshot comparison or Percy', 'Karma', 'Jest'], correctIndex: 1, explanation: 'Playwright has built-in screenshot comparison capabilities, and tools like Percy extend this with cloud-based visual testing infrastructure.' }
