      { id: 1, question: 'How do you test a service that makes HTTP calls?', options: ['Use real HTTP requests', 'Use HttpTestingController to intercept and mock requests', 'Use fetch API', 'Skip HTTP testing'], correctIndex: 1, explanation: 'HttpTestingController from Angular allows you to intercept HTTP requests during tests and provide mock responses without making real network calls.' },
      { id: 2, question: 'What should you always do after HTTP tests?', options: ['Log to console', 'Call httpMock.verify() to ensure no unexpected requests were made', 'Reset TestBed', 'Clear local storage'], correctIndex: 1, explanation: 'Calling httpMock.verify() in afterEach ensures that all expected HTTP requests were made and no unexpected requests slipped through.' },
      { id: 3, question: 'How do you test a service using BehaviorSubject?', options: ['It cannot be tested', 'Subscribe to the observable and verify emitted values match expected state', 'Use setTimeout', 'Use async/await only'], correctIndex: 1, explanation: 'Subscribe to the BehaviorSubject and verify that the emitted values match the expected state changes after operations are performed.' }
